components.css:
.ds-primary { display: inline-flex; align-items: center; justify-content: center; gap: .75rem; min-height: 3.25rem; padding: .625rem 1.125rem; border: 1px solid transparent; border-radius: var(--control-radius, .5rem); background: var(--peach, #f4c5ae); color: var(--ink, #192724); font: 800 1rem/1.55 var(--font, Manrope, system-ui, sans-serif); text-align: center; cursor: pointer; }
.ds-primary:hover { background: var(--peach-hover, #efb69a); }
.ds-primary:active { background: var(--peach-active, #e9a889); }
.ds-primary:disabled { background: var(--subtle, #edece2); color: var(--muted, #505b54); cursor: wait; }
.ds-primary .ds-icon { width: 1.25rem; height: 1.25rem; flex: none; }
.ds-primary:focus-visible { outline: 2px solid var(--focus, #8c3f26); outline-offset: 4px; }
.ds-primary { transition: background-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)), border-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)); }
@media (prefers-reduced-motion: reduce) { .ds-primary { transition: none; } }

.ds-secondary { display: inline-flex; align-items: center; justify-content: center; gap: .75rem; min-height: 3.25rem; padding: .625rem 1.125rem; border: 1px solid var(--field-line, #8c9287); border-radius: var(--control-radius, .5rem); background: var(--paper, #fffdf8); color: var(--ink, #192724); font: 800 1rem/1.55 var(--font, Manrope, system-ui, sans-serif); text-align: center; cursor: pointer; }
.ds-secondary:hover { background: var(--peach-hover, #efb69a); }
.ds-secondary:active { background: var(--peach-active, #e9a889); }
.ds-secondary:disabled { background: var(--subtle, #edece2); color: var(--muted, #505b54); cursor: wait; }
.ds-secondary .ds-icon { width: 1.25rem; height: 1.25rem; flex: none; }
.ds-secondary:focus-visible { outline: 2px solid var(--focus, #8c3f26); outline-offset: 4px; }
.ds-secondary { transition: background-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)), border-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)); }
@media (prefers-reduced-motion: reduce) { .ds-secondary { transition: none; } }

.ds-row-action { display: inline-flex; align-items: center; justify-content: center; gap: .5rem; min-height: 2.75rem; box-sizing: border-box; padding: .4375rem .75rem; border: 1px solid var(--line, #d6d5c8); border-radius: var(--control-radius, .5rem); color: var(--ink, #192724); font: 800 .875rem/1.55 var(--font, Manrope, system-ui, sans-serif); text-decoration: none; }
.ds-row-action .ds-icon { width: 1rem; height: 1rem; flex: none; }
.ds-row-action:hover { border-color: var(--field-line, #8c9287); background: var(--subtle, #edece2); }
.ds-row-action:active { background: var(--peach, #f4c5ae); }
.ds-row-action:focus-visible { outline: 2px solid var(--focus, #8c3f26); outline-offset: 4px; }
.ds-row-action { transition: background-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)), border-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)); }
@media (prefers-reduced-motion: reduce) { .ds-row-action { transition: none; } }

.ds-back { display: inline-flex; align-items: center; gap: .5rem; min-height: 2.75rem; color: var(--ink, #192724); font: 800 .875rem/1.55 var(--font, Manrope, system-ui, sans-serif); text-decoration: none; text-underline-offset: .25em; }
.ds-back .ds-icon { width: 1rem; height: 1rem; flex: none; }
.ds-back:hover { text-decoration: underline; }
.ds-back:focus-visible { outline: 2px solid var(--focus, #8c3f26); outline-offset: 4px; }
.ds-back { transition: background-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)), border-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)); }
@media (prefers-reduced-motion: reduce) { .ds-back { transition: none; } }

.ds-field { display: grid; gap: .4375rem; min-width: 0; color: var(--ink, #192724); font: 400 1rem/1.55 var(--font, Manrope, system-ui, sans-serif); }
.ds-field label { font-size: .875rem; font-weight: 800; line-height: 1.25rem; }
.ds-field input { box-sizing: border-box; width: 100%; min-width: 0; min-height: 3.25rem; padding: .625rem .75rem; border: 1px solid var(--field-line, #8c9287); border-radius: var(--control-radius, .5rem); background: var(--paper, #fffdf8); color: var(--ink, #192724); caret-color: var(--focus, #8c3f26); font: inherit; }
.ds-field input:hover { border-color: var(--ink, #192724); } .ds-field input[aria-invalid="true"] { border-color: var(--error, #a03427); }
.ds-field input:focus-visible { outline: 2px solid var(--focus, #8c3f26); outline-offset: 4px; }
.ds-field input { transition: background-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)), border-color 160ms var(--ease-out, cubic-bezier(.22, 1, .36, 1)); }
@media (prefers-reduced-motion: reduce) { .ds-field input { transition: none; } }

.ds-trip { padding: var(--panel-padding, 1.75rem); border: 1px solid var(--line, #d6d5c8); border-radius: var(--radius, .875rem); background: var(--paper, #fffdf8); color: var(--ink, #192724); font: 400 1rem/1.55 var(--font, Manrope, system-ui, sans-serif); }
.ds-trip-heading { display: flex; align-items: center; gap: .875rem; }
.ds-trip-heading h2 { margin: 0; font-size: 1.625rem; font-weight: 800; letter-spacing: -.035em; line-height: 1.12; overflow-wrap: anywhere; }
.ds-trip-heading p { margin: .1875rem 0 0; color: var(--muted, #505b54); font-size: .875rem; }
.ds-trip-icon { display: grid; place-items: center; width: 3rem; height: 3rem; flex: none; border-radius: var(--control-radius, .5rem); background: var(--subtle, #edece2); }
.ds-trip-icon .ds-icon { width: 1.5rem; height: 1.5rem; }
.ds-itinerary { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; margin: 1.25rem 0 0; padding-top: 1.25rem; border-top: 1px solid var(--line, #d6d5c8); }
.ds-itinerary dt { color: var(--muted, #505b54); font-size: .875rem; font-weight: 700; } .ds-itinerary dd { margin: .1875rem 0 0; font-weight: 800; overflow-wrap: anywhere; }
.ds-itinerary-location { grid-column: 1 / -1; } .ds-itinerary-location dt { display: flex; align-items: center; gap: .25rem; } .ds-itinerary-location .ds-icon { width: 1rem; height: 1rem; }
@media (max-width: 48rem) { .ds-trip-heading h2 { font-size: 1.375rem; } }

.ds-steps { display: flex; flex-wrap: wrap; align-items: center; gap: .625rem 1.125rem; margin: 0; padding: 0; list-style: none; color: var(--muted, #505b54); font: 700 .8125rem/1.55 var(--font, Manrope, system-ui, sans-serif); }
.ds-steps li { display: flex; align-items: center; gap: .5rem; } .ds-steps li + li::before { content: ""; width: 1.25rem; margin-inline-end: .5625rem; border-top: 1px solid var(--field-line, #8c9287); }
.ds-steps span { display: grid; place-items: center; width: 1.375rem; height: 1.375rem; box-sizing: border-box; border: 1px solid var(--field-line, #8c9287); border-radius: 50%; font-size: .6875rem; font-variant-numeric: tabular-nums; }
.ds-steps [aria-current] { color: var(--ink, #192724); } .ds-steps [aria-current] span { border-color: var(--ink, #192724); background: var(--ink, #192724); color: var(--paper, #fffdf8); }
@media (max-width: 30rem) { .ds-steps { gap: .5rem .625rem; font-size: .6875rem; } .ds-steps li { gap: .3125rem; } .ds-steps li + li::before { width: .375rem; margin-inline-end: .125rem; } .ds-steps span { width: 1.125rem; height: 1.125rem; } }

.ds-receipt { border-radius: var(--radius, .875rem); background: var(--ink, #192724); color: var(--paper, #fffdf8); font: 400 1rem/1.55 var(--font, Manrope, system-ui, sans-serif); }
.ds-receipt-header { display: grid; align-content: center; min-height: 7.5625rem; gap: .4375rem; box-sizing: border-box; padding: 1.125rem var(--panel-padding, 1.75rem); }
.ds-receipt-header h2 { margin: 0; color: var(--peach, #f4c5ae); font-size: .875rem; font-weight: 800; line-height: 1.12; }
.ds-receipt-detail { position: relative; margin: 0; padding: .5rem var(--panel-padding, 1.75rem); border-top: 1px dashed var(--field-line, #8c9287); }
.ds-receipt-detail::before, .ds-receipt-detail::after { position: absolute; inset-block-start: -.4375rem; width: .875rem; height: .875rem; border-radius: 50%; background: var(--ground, #f5f2e9); content: ""; pointer-events: none; }
.ds-receipt-detail::before { inset-inline-start: -.4375rem; } .ds-receipt-detail::after { inset-inline-end: -.4375rem; }
.ds-receipt-detail > div { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, auto); align-items: baseline; gap: .75rem; padding-block: .75rem; }
.ds-receipt-detail > div + div { border-top: 1px solid var(--muted, #505b54); }
.ds-receipt-detail dt { font-size: .875rem; font-weight: 700; }
.ds-receipt-detail dd { max-width: 15ch; margin: 0; font-size: .875rem; font-weight: 800; font-variant-numeric: tabular-nums; text-align: end; overflow-wrap: anywhere; }
.ds-total { margin: 0; font-size: 2.375rem; font-weight: 800; line-height: 1.12; letter-spacing: -.035em; font-variant-numeric: tabular-nums; overflow-wrap: anywhere; }
.ds-billing-note { display: block; margin-top: .1875rem; color: #dcdfd3; font-size: .8125rem; font-weight: 400; }
@media (max-width: 48rem) { .ds-total { font-size: 2.125rem; } }

